<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Composition with Red, Blue and Yellow (1930) by Piet Mondrian</title>
<meta name="description" content="The story of Piet Mondrian's 1930 painting Composition with Red, Blue and Yellow and the De Stijl movement.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Big+Shoulders+Display:wght@700;900&family=Instrument+Sans:wght@400;600&display=swap" rel="stylesheet">
<style>
  :root {
    --red: #cc1f1a;
    --blue: #17398c;
    --yellow: #f6cf1d;
    --white: #fff;
    --grey: #a9a9a9;
    --black: #000;
    --line: clamp(10px, 1.3vw, 20px);
    --pad: clamp(1.25rem, 2.6vw, 2.75rem);
    --display: "Big Shoulders Display", "Arial Narrow", Impact, sans-serif;
    --body: "Instrument Sans", Arial, sans-serif;
  }
  * { box-sizing: border-box; margin: 0; }
  html { scroll-behavior: smooth; }
  body {
    background: var(--black);
    color: var(--black);
    font: 400 clamp(1.0625rem, 0.5vw + 0.95rem, 1.25rem)/1.5 var(--body);
  }

  /* The black ground showing through the grid gap is what draws every line. */
  .canvas {
    display: grid;
    grid-template-columns: repeat(12, minmax(0, 1fr));
    gap: var(--line);
    padding-bottom: var(--line);
  }
  .cell { padding: var(--pad); background: var(--white); min-width: 0; }
  .red { background: var(--red); color: var(--white); }
  .blue { background: var(--blue); color: var(--white); }
  .yellow { background: var(--yellow); }

  h1, h2, .year-numeral {
    font-family: var(--display);
    font-weight: 900;
    line-height: 0.92;
  }
  h2 { font-size: clamp(2.75rem, 5.5vw, 5.5rem); margin-bottom: 0.35em; }
  h3 {
    font-family: var(--display);
    font-weight: 700;
    font-size: clamp(1.75rem, 2.5vw, 2.5rem);
    line-height: 1;
    margin-bottom: 0.5em;
  }
  p { max-width: 34em; }
  p + p { margin-top: 0.75em; }

  /* Hero: the page opens as the painting, red top right, blue and yellow low. */
  .hero { min-height: 100svh; grid-template-rows: minmax(0, 1fr) minmax(0, 1fr) auto; }
  .hero-byline { grid-column: 1 / span 3; grid-row: 1; font-weight: 600; }
  .hero-empty { grid-column: 1 / span 3; grid-row: 2; }
  .hero-title { grid-column: 4 / -1; grid-row: 1 / span 2; display: flex; align-items: flex-end; }
  .hero-title h1 { font-size: min(10.8vw, 21svh); }
  .hero-title span { display: block; }
  .hero-blue { grid-column: 1 / span 3; grid-row: 3; }
  .hero-intro { grid-column: 4 / span 7; grid-row: 3; }
  .hero-yellow { grid-column: 11 / -1; grid-row: 3; }
  .hero-intro p { margin-bottom: 1.1em; }

  /* The one orchestrated moment: colour enters in the order the eye reads it. */
  @media (prefers-reduced-motion: no-preference) {
    .hero-title, .hero-blue, .hero-yellow { animation: colour-in 0.7s cubic-bezier(.7, 0, .2, 1) backwards; }
    .hero-title { animation-delay: 0.15s; }
    .hero-blue { animation-delay: 0.65s; }
    .hero-yellow { animation-delay: 0.95s; }
  }
  @keyframes colour-in { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0); } }

  .button {
    display: inline-block;
    padding: 0.8em 1.3em;
    background: var(--black);
    color: var(--white);
    font-family: var(--display);
    font-weight: 700;
    font-size: 1.5rem;
    line-height: 1.1;
    text-decoration: none;
    border: 0.25rem solid var(--black);
  }
  .button:hover { background: var(--white); color: var(--black); }
  a:focus-visible {
    outline: 4px solid var(--black);
    outline-offset: 2px;
    box-shadow: 0 0 0 2px var(--white), 0 0 0 10px var(--white);
  }

  .painter { grid-column: 1 / span 7; }
  .year { grid-column: 8 / -1; }
  .year-numeral { font-size: clamp(6rem, 17vw, 17rem); margin-bottom: 0.1em; }

